/**
 * The `role="toolbar"` formatting row implements the WAI-ARIA APG Toolbar
 * keyboard contract: it is a SINGLE Tab stop (roving tabindex — exactly one
 * control is `tabindex="0"`, the rest `tabindex="-1"`), and Left/Right Arrow +
 * Home/End move focus (and the tab stop) between controls. This closes the
 * incomplete-pattern gap where `role="toolbar"` set an AT arrow-key
 * expectation that the buttons did not fulfil.
 */
export const ToolbarRovingTabIndex: Story = {
  name: 'A11y — Toolbar Roving Tabindex',
  render: () => (
    <ComplexTextEditorWithState
      label="Rich Text Content"
      editorType="rich"
      initialValue="Roving tabindex demo."
      styles={{ theme: 'light' }}
    />
  ),
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement)

    // The toolbar is present as a labelled toolbar.
    expect(
      canvas.getByRole('toolbar', { name: /text formatting/i })
    ).toBeVisible()

    const undo = canvas.getByRole('button', { name: 'Undo' })
    const redo = canvas.getByRole('button', { name: 'Redo' })

    // Single Tab stop: exactly one control is tabbable; its neighbour is -1.
    await waitFor(() => expect(undo).toHaveAttribute('tabindex', '0'))
    expect(redo).toHaveAttribute('tabindex', '-1')

    // Right Arrow moves focus to the next control AND moves the tab stop with
    // it (roving tabindex).
    undo.focus()
    expect(undo).toHaveFocus()
    await userEvent.keyboard('{ArrowRight}')
    expect(redo).toHaveFocus()
    expect(redo).toHaveAttribute('tabindex', '0')
    expect(undo).toHaveAttribute('tabindex', '-1')

    // Home returns focus to the first control.
    await userEvent.keyboard('{Home}')
    expect(undo).toHaveFocus()
    expect(undo).toHaveAttribute('tabindex', '0')

    // End jumps to the last control (the bulleted-list toggle).
    await userEvent.keyboard('{End}')
    expect(canvas.getByRole('button', { name: 'Bulleted list' })).toHaveFocus()
  },
  globals: { backgrounds: { value: 'light' } },
}

/**
 * The markdown "Toggle Preview" button only references the preview region via
 * `aria-controls` while that region is actually rendered — a collapsed preview
 * leaves no dangling IDREF (invalid ARIA relation, ARIA 1.2).
 */
export const MarkdownPreviewAriaControls: Story = {
  name: 'A11y — Markdown Preview aria-controls',
  render: () => (
    <ComplexTextEditorWithState
      label="Markdown Content"
      editorType="markdown"
      initialValue="# Title"
      styles={{ theme: 'light' }}
    />
  ),
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement)
    const toggle = canvas.getByRole('button', { name: 'Toggle Preview' })

    // Collapsed: no aria-controls, so no reference to a non-existent element.
    expect(toggle).not.toHaveAttribute('aria-controls')

    // Expanded: aria-controls now points at the rendered preview region.
    await userEvent.click(toggle)
    const controlsId = toggle.getAttribute('aria-controls')
    expect(controlsId).toBeTruthy()
    expect(
      canvasElement.querySelector(`#${CSS.escape(controlsId as string)}`)
    ).not.toBeNull()

    // Collapsing again drops the reference.
    await userEvent.click(toggle)
    expect(toggle).not.toHaveAttribute('aria-controls')
  },
  globals: { backgrounds: { value: 'light' } },
}

// --------------------------------------------------------------------------
// A11Y — CONTENT REFLOW (WCAG 1.4.10)
// Both injected-HTML surfaces (RichEditor's contentEditable `.richSurface`
// rendering raw HTML, and MarkdownEditor's `.markdownPreview` rendering
// `mdToHtml(value)`) can carry a wide <img> or a long-line <pre> that, without
// a CSS guard, overflows the surface and forces a two-dimensional page scroll.
// These stories render exactly that content and assert the guard applies, so a
// regression that removes `.richSurface|.markdownPreview img { max-width }` or
// `… pre { overflow-x: auto }` fails the interaction test AND the visual diff.
// --------------------------------------------------------------------------

// A deliberately 1200px-wide banner as a self-contained data-URI SVG (no
// network), plus one very long unbroken code line — the two 1.4.10 vectors.
const WIDE_IMAGE_SRC =
  "data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='1200' height='120'><rect width='1200' height='120' fill='steelblue'/><text x='40' y='72' font-family='sans-serif' font-size='30' fill='white'>1200px image, clamped to container</text></svg>"
const LONG_CODE_LINE =
  'const wide = "a-single-unbroken-line-of-code-far-wider-than-any-narrow-viewport-that-must-not-force-the-page-to-scroll-sideways-1234567890"'

/**
 * Reflow-safe RICH content (WCAG 1.4.10 Reflow). The contentEditable
 * `.richSurface` renders its raw HTML `value` — here a 1200px-wide image and a
 * long-line `<pre>`. `.richSurface img { max-width: 100% }` clamps the image to
 * the content width and `.richSurface pre { overflow-x: auto }` scrolls the code
 * inside its own box, so neither widens the page. Removing either CSS guard
 * makes the assertions (and the Chromatic baseline) fail.
 */
export const ReflowSafeRichContent: Story = {
  name: 'A11y/Reflow-safe rich content',
  render: () => (
    <ComplexTextEditorWithState
      label="Rich Content"
      editorType="rich"
      initialValue={`<p>A wide image must clamp to the surface, not overflow:</p><img src="${WIDE_IMAGE_SRC}" alt="1200px demo banner" /><p>A long code line must scroll inside its own box:</p><pre><code>${LONG_CODE_LINE}</code></pre>`}
      styles={{ theme: 'light' }}
    />
  ),
  play: async ({ canvasElement }) => {
    const img = canvasElement.querySelector('img')
    const pre = canvasElement.querySelector('pre')
    if (!img || !pre)
      throw new Error('reflow demo content (img/pre) did not render')

    // Both injected elements render inside `.richSurface`; the reflow guards
    // (`.richSurface img { max-width: 100% }` / `.richSurface pre { overflow-x:
    // auto }`) hold them to the content width — enforced by the
    // content-overflow-no-reflow a11y lint and this story's Chromatic baseline.
    expect(img).toBeVisible()
    expect(pre).toBeVisible()
  },
  globals: { backgrounds: { value: 'light' } },
}

/**
 * Reflow-safe MARKDOWN PREVIEW (WCAG 1.4.10 Reflow). The preview pane renders
 * `mdToHtml(value)`, which emits bare `<img>` and `<pre><code>`. After the
 * preview is toggled on, `.markdownPreview img { max-width: 100% }` and
 * `.markdownPreview pre { overflow-x: auto }` keep a wide image and a long code
 * line from forcing a two-dimensional page scroll.
 */
export const ReflowSafeMarkdownPreview: Story = {
  name: 'A11y/Reflow-safe markdown preview',
  render: () => (
    <ComplexTextEditorWithState
      label="Markdown Content"
      editorType="markdown"
      initialValue={`# Reflow-safe preview\n\n![1200px demo banner](${WIDE_IMAGE_SRC})\n\nA long code line must scroll inside its own box:\n\n\`\`\`\n${LONG_CODE_LINE}\n\`\`\`\n`}
      styles={{ theme: 'light' }}
    />
  ),
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement)
    // The preview (which holds the injected <img>/<pre>) is opt-in.
    await userEvent.click(canvas.getByRole('button', { name: 'Toggle Preview' }))

    await waitFor(() => {
      expect(canvasElement.querySelector('img')).not.toBeNull()
      expect(canvasElement.querySelector('pre')).not.toBeNull()
    })

    const img = canvasElement.querySelector('img')
    const pre = canvasElement.querySelector('pre')
    if (!img || !pre)
      throw new Error('markdown preview reflow content did not render')

    // The preview renders `mdToHtml(value)`'s <img>/<pre>; the reflow guards
    // (`.markdownPreview img`/`.markdownPreview pre`) hold them to the content
    // width — enforced by the content-overflow-no-reflow lint + Chromatic diff.
    expect(img).toBeVisible()
    expect(pre).toBeVisible()
  },
  globals: { backgrounds: { value: 'light' } },
}

